    document.cookie = `.AspNetCore.Culture=c=${lang}|uic=${lang}; expires=${date.toUTCString()}; path=/dtcms`;
    document.cookie = `.AspNetCore.Culture=c=${lang}|uic=${lang}; expires=${date.toUTCString()}; path=/Dtcms`;
    document.cookie = `.AspNetCore.Culture=c=${lang}|uic=${lang}; expires=${date.toUTCString()}; path=/DTCMS`;
