;// ./wwwroot/DTCMS/assets/ts/pages/dashboard/settings/injectCode/index.ts




let injectCode_instances = document.querySelectorAll(".code__container");
Array.from(injectCode_instances).forEach((item) => {
    let language = new Compartment(), tabSize = new Compartment();
    let inputId = item.getAttribute("data-codinput-target");
    let input = document.querySelector(`#${inputId}`);
    let state = EditorState.create({
        doc: input.value,
        extensions: [
            dracula,
            basicSetup,
            language.of(dist_html()),
            tabSize.of(EditorState.tabSize.of(8)),
            EditorView.updateListener.of((update) => {
                if (update.docChanged) {
                    input.value = update.state.doc.toString();
                }
            }),
        ],
    });
    new EditorView({
        state,
        parent: item,
    });
});

